            if spans and a<=spans[-1][1]+1: spans[-1]=(spans[-1][0],max(spans[-1][1],b))
            else: spans.append((a,b))
        for a,b in spans:
            for j in range(a,b): print(f'{j+1:5d}: {lines[j]}')
